    ("random: twist parity", R, "((next & 1) != 0 ? kMatrix : 0)", "((word & 1) != 0 ? kMatrix : 0)"),
    ("random: twist mix", R, "(word & kUpper) | (next & kLower)", "(next & kUpper) | (word & kLower)"),
    ("random: first loop bound", R, "for (; i < kCount - kMiddle; i++) {", "for (; i < kCount - kMiddle - 1; i++) {"),
    ("random: second far", R, "m_state[i + kMiddle - kCount]", "m_state[i + kMiddle - kCount + 1]"),
    ("random: last word", R, "Twist(m_state[kCount - 1], m_state[0], m_state[kMiddle - 1])", "Twist(m_state[kCount - 1], m_state[0], m_state[kMiddle])"),
    ("random: regenerate index", R, "    m_index = 0;\n    m_state[kCount - 1]", "    m_index = 1;\n    m_state[kCount - 1]"),
