    ("random: temper 18", R, "return y ^ (y >> 18);", "return y ^ (y >> 17);"),
    ("random: below zero", R, "    if (bound == 0) {\n        return 0;", "    if (bound == 0) {\n        return 1;"),
    ("random: below", R, "return Next() % bound;", "return Next() % (bound + 1);"),
